-- PostgreSQL 시험용 예시 스키마. 빈 시험 DB 의 public 에 넣는다 (test/helpers/pg-sample.ts 가 mst_brand 가 없을 때만 넣는다).
-- 접두어 그룹 mst(마스터), whs(창고 업무), sys(시스템), 공통 컬럼(reg_id, reg_dt, mod_id, mod_dt), 복합 PK, 연결 테이블,
-- UNIQUE, 인덱스, 시퀀스 기본값, identity, 함수, 코멘트를 고루 담는다. 실데이터는 없다.

CREATE SEQUENCE mst_brand_seq START 1;
CREATE SEQUENCE mst_center_seq START 1;

CREATE TABLE mst_brand (
  brand_seq integer NOT NULL DEFAULT nextval('mst_brand_seq'::regclass),
  brand_cd varchar(20) NOT NULL,
  brand_nm varchar(100) NOT NULL,
  ceo_nm varchar(50),
  use_yn char(1) NOT NULL DEFAULT 'Y'::bpchar,
  reg_id varchar(20),
  reg_dt timestamp DEFAULT now(),
  mod_id varchar(20),
  mod_dt timestamp,
  PRIMARY KEY (brand_seq),
  CONSTRAINT uq_brand_cd UNIQUE (brand_cd)
);
COMMENT ON TABLE mst_brand IS '브랜드';
COMMENT ON COLUMN mst_brand.brand_seq IS '브랜드 SEQ';
COMMENT ON COLUMN mst_brand.brand_nm IS '브랜드 이름';
COMMENT ON COLUMN mst_brand.ceo_nm IS '대표자';

CREATE TABLE mst_center (
  center_seq integer NOT NULL DEFAULT nextval('mst_center_seq'::regclass),
  center_nm varchar(100) NOT NULL,
  brand_seq integer,
  reg_id varchar(20),
  reg_dt timestamp DEFAULT now(),
  mod_id varchar(20),
  mod_dt timestamp,
  PRIMARY KEY (center_seq),
  CONSTRAINT fk_center_brand FOREIGN KEY (brand_seq) REFERENCES mst_brand (brand_seq)
);
COMMENT ON TABLE mst_center IS '물류센터';

CREATE TABLE mst_wh (
  wh_seq integer NOT NULL,
  wh_nm varchar(100) NOT NULL,
  center_seq integer,
  reg_id varchar(20),
  reg_dt timestamp DEFAULT now(),
  mod_id varchar(20),
  mod_dt timestamp,
  PRIMARY KEY (wh_seq),
  CONSTRAINT fk_wh_center FOREIGN KEY (center_seq) REFERENCES mst_center (center_seq)
);
COMMENT ON TABLE mst_wh IS '창고';
CREATE INDEX ix_wh_center ON mst_wh (center_seq);

CREATE TABLE mst_brand_wh (
  brand_seq integer NOT NULL,
  wh_seq integer NOT NULL,
  sort_no integer DEFAULT 0,
  PRIMARY KEY (brand_seq, wh_seq),
  CONSTRAINT fk_brand_wh_brand FOREIGN KEY (brand_seq) REFERENCES mst_brand (brand_seq),
  CONSTRAINT fk_brand_wh_wh FOREIGN KEY (wh_seq) REFERENCES mst_wh (wh_seq)
);
COMMENT ON TABLE mst_brand_wh IS '브랜드별 창고';

CREATE TABLE mst_brand_center (
  brand_seq integer NOT NULL,
  center_seq integer NOT NULL,
  PRIMARY KEY (brand_seq, center_seq),
  CONSTRAINT fk_brand_center_brand FOREIGN KEY (brand_seq) REFERENCES mst_brand (brand_seq),
  CONSTRAINT fk_brand_center_center FOREIGN KEY (center_seq) REFERENCES mst_center (center_seq)
);
COMMENT ON TABLE mst_brand_center IS '브랜드별 센터';

CREATE TABLE mst_user (
  user_id varchar(20) NOT NULL,
  user_nm varchar(50) NOT NULL,
  brand_seq integer,
  reg_id varchar(20),
  reg_dt timestamp DEFAULT now(),
  mod_id varchar(20),
  mod_dt timestamp,
  PRIMARY KEY (user_id),
  CONSTRAINT fk_user_brand FOREIGN KEY (brand_seq) REFERENCES mst_brand (brand_seq)
);
COMMENT ON TABLE mst_user IS '사용자';

CREATE TABLE whs_stock (
  stock_seq bigint GENERATED BY DEFAULT AS IDENTITY,
  wh_seq integer NOT NULL,
  item_cd varchar(30) NOT NULL,
  qty numeric(15,3) NOT NULL DEFAULT 0,
  PRIMARY KEY (stock_seq),
  CONSTRAINT fk_stock_wh FOREIGN KEY (wh_seq) REFERENCES mst_wh (wh_seq),
  CONSTRAINT uq_stock_wh_item UNIQUE (wh_seq, item_cd)
);
COMMENT ON TABLE whs_stock IS '재고';

CREATE TABLE whs_in_h (
  in_no varchar(20) NOT NULL,
  wh_seq integer NOT NULL,
  in_dt date NOT NULL,
  reg_id varchar(20),
  reg_dt timestamp DEFAULT now(),
  mod_id varchar(20),
  mod_dt timestamp,
  PRIMARY KEY (in_no),
  CONSTRAINT fk_in_h_wh FOREIGN KEY (wh_seq) REFERENCES mst_wh (wh_seq)
);
COMMENT ON TABLE whs_in_h IS '입고 헤더';

CREATE TABLE sys_code (
  code_grp varchar(20) NOT NULL,
  code varchar(20) NOT NULL,
  code_nm varchar(100) NOT NULL,
  PRIMARY KEY (code_grp, code)
);
COMMENT ON TABLE sys_code IS '공통코드';

CREATE TABLE sys_log (
  log_seq bigint GENERATED ALWAYS AS IDENTITY,
  msg text,
  reg_dt timestamp DEFAULT now(),
  PRIMARY KEY (log_seq)
);
COMMENT ON TABLE sys_log IS '로그';

CREATE OR REPLACE FUNCTION fn_lpad(a_string text, a_length integer, a_pad text)
 RETURNS text
 LANGUAGE sql
AS $function$ select lpad(a_string, a_length, a_pad) $function$;
